gcB3(){return"\u067e\u0633 \u0627\u0632 \u067e\u0634\u062a\u06cc\u0628\u0627\u0646\u200c\u06af\u06cc\u0631\u06cc\u060c \u0628\u0631\u06af\u0634\u062a \u0627\u0632 \u0633\u0627\u0644 \u0645\u0627\u0644\u06cc \u062f\u06cc\u06af\u0631 \u0645\u062c\u0627\u0632 \u0646\u06cc\u0633\u062a. \u0627\u062d\u062a\u0645\u0627\u0644\u0627\u064b \u0648\u0636\u0639\u06cc\u062a \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062a\u063a\u06cc\u06cc\u0631 \u06a9\u0631\u062f\u0647. \u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634 \u0631\u0627 \u0628\u0631\u0631\u0633\u06cc \u0648 \u062f\u0648\u0628\u0627\u0631\u0647 \u062a\u0644\u0627\u0634 \u06a9\u0646\u06cc\u062f."},
gcBx(){return"\u06a9\u062f \u062a\u0623\u06cc\u06cc\u062f \u067e\u0633 \u0627\u0632 \u067e\u0634\u062a\u06cc\u0628\u0627\u0646 \u062f\u0631\u06cc\u0627\u0641\u062a \u0646\u0634\u062f. \xab\u0628\u0647\u200c\u0631\u0648\u0632\u0631\u0633\u0627\u0646\u06cc \u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634\xbb \u0631\u0627 \u0628\u0632\u0646\u06cc\u062f."},
gcBz(){return"\u06a9\u062f \u062a\u0623\u06cc\u06cc\u062f \u062f\u0631 \u062f\u0633\u062a\u0631\u0633 \u0646\u06cc\u0633\u062a."},
gcBq(){return"\u062f\u0631 \u062d\u0627\u0644 \u062d\u0630\u0641 \u0633\u0627\u0644 \u0645\u0627\u0644\u06cc \u062c\u0627\u0631\u06cc\u2026"},
gcBv(){return"\u0628\u0627 \u0645\u0648\u0641\u0642\u06cc\u062a \u0627\u0646\u062c\u0627\u0645 \u0634\u062f"},
gcBA(){return"\u0627\u06cc\u0646 \u0639\u0645\u0644\u06cc\u0627\u062a \u062a\u0645\u0627\u0645 \u0627\u0633\u0646\u0627\u062f \u0633\u0627\u0644 \u0645\u0627\u0644\u06cc \u062c\u0627\u0631\u06cc \u0631\u0627 \u062d\u0630\u0641 \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0633\u0627\u0644 \u0642\u0628\u0644 \u0631\u0627 \u062f\u0648\u0628\u0627\u0631\u0647 \xab\u062c\u0627\u0631\u06cc\xbb \u0645\u06cc\u200c\u06a9\u0646\u062f."},
gcBh(){return"\u0633\u0627\u0644 \u062c\u0627\u0631\u06cc (\u062d\u0630\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f)"},
bmM(a){return"\u0634\u0646\u0627\u0633\u0647 "+a},
gcBn(){return"\u0633\u0627\u0644 \u0628\u0639\u062f\u06cc \u062c\u0627\u0631\u06cc"},
cBi(a){return"\u062a\u0639\u062f\u0627\u062f \u0627\u0633\u0646\u0627\u062f \u0633\u0627\u0644 \u062c\u0627\u0631\u06cc: "+a},
cBc(a){return"\u0627\u0633\u0646\u0627\u062f \u0628\u0633\u062a\u0646 \u0633\u0627\u0644 \u0631\u0648\u06cc \u0633\u0627\u0644 \u0642\u0628\u0644 \u06a9\u0647 \u062d\u0630\u0641 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f: "+a},
gcB5(){return"\u0642\u0628\u0644 \u0627\u0632 \u062d\u0630\u0641 \u0633\u0627\u0644\u060c \u067e\u0634\u062a\u06cc\u0628\u0627\u0646 \u06a9\u0627\u0645\u0644 \u0628\u06af\u06cc\u0631\u0645"},
gcB4(){return"\u0647\u0645\u0627\u0646 \u067e\u0634\u062a\u06cc\u0628\u0627\u0646 \u0633\u06cc\u0633\u062a\u0645\u06cc (.hbx) \u0627\u0632 \u0628\u062e\u0634 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a\u061b \u0628\u0631\u0627\u06cc \u0628\u0627\u0632\u06cc\u0627\u0628\u06cc \u062f\u0631 \u0635\u0648\u0631\u062a \u0646\u06cc\u0627\u0632."},
gcBo(){return"\u0628\u0627\u0632 \u06a9\u0631\u062f\u0646 \u0635\u0641\u062d\u0647\u0654 \u067e\u0634\u062a\u06cc\u0628\u0627\u0646\u200c\u06af\u06cc\u0631\u06cc"},
