gcCE(){return"\u0647\u0631 N \u0633\u0627\u0639\u062a"},
gcCD(){return"\u0633\u0627\u0639\u0627\u062a \u062b\u0627\u0628\u062a \u0631\u0648\u0632\u0627\u0646\u0647"},
gcCx(){return"\u0628\u0627\u0632\u0647"},
cCu(a){return"\u0647\u0631 "+a+" \u0633\u0627\u0639\u062a"},
gcCr(){return"\u0627\u0641\u0632\u0648\u062f\u0646 \u0633\u0627\u0639\u062a (HH:MM)"},
gcCq(){return"\u0627\u0641\u0632\u0648\u062f\u0646"},
gcCz(){return"\u0633\u0627\u0639\u062a \u0646\u0627\u0645\u0639\u062a\u0628\u0631 \u0627\u0633\u062a. \u0641\u0631\u0645\u062a HH:MM (\u0645\u062b\u0644\u0627\u064b \u06f0\u06f9:\u06f0\u06f0)."},
cD6(a){return"\u0633\u0627\u0639\u0627\u062a \u0628\u0631 \u0627\u0633\u0627\u0633 \u0645\u0646\u0637\u0642\u0647 \u0632\u0645\u0627\u0646\u06cc: "+a},
